import{_ as a,o as s,c as i,an as n}from"./chunks/framework.DlpU30wy.js";const h=JSON.parse('{"title":"Dimensions","description":"Dimensions in DimensionalData.jl - named wrapper types for array axes, including spatial (X,Y,Z) and temporal (Ti) dimensions, and more!","frontmatter":{"description":"Dimensions in DimensionalData.jl - named wrapper types for array axes, including spatial (X,Y,Z) and temporal (Ti) dimensions, and more!"},"headers":[],"relativePath":"dimensions.md","filePath":"dimensions.md","lastUpdated":null}'),o={name:"dimensions.md"};function t(p,e,d,l,c,r){return s(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="Dimensions" tabindex="-1">Dimensions <a class="header-anchor" href="#Dimensions" aria-label="Permalink to &quot;Dimensions {#Dimensions}&quot;">​</a></h1><p>Dimensions are &quot;wrapper types&quot; that can be used to wrap any object to associate it with a named dimension.</p><p><code>X</code>, <code>Y</code>, <code>Z</code>, <code>Ti</code> are predefined as types:</p><div class="language-@ansi vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">@ansi</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>using DimensionalData</span></span>
<span class="line"><span>X(1)</span></span>
<span class="line"><span>X(1), Y(2), Z(3)</span></span></code></pre></div><p>You can also create <a href="/DimensionalData.jl/dev/api/dimensions#DimensionalData.Dimensions.Dim"><code>Dim</code></a> dimensions with any name:</p><div class="language-@ansi vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">@ansi</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Dim{:a}(1), Dim{:b}(1)</span></span></code></pre></div><p>The wrapped value can be retrieved with <code>val</code>:</p><div class="language-@ansi vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">@ansi</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>val(X(1))</span></span></code></pre></div><p>DimensionalData.jl uses <code>Dimensions</code> everywhere:</p><ul><li><p><code>Dimension</code>s are returned from <code>dims</code> to specify the names of the dimensions of an object</p></li><li><p>They can wrap <a href="/DimensionalData.jl/dev/api/lookuparrays#DimensionalData.Dimensions.Lookups"><code>Dimensions.Lookups</code></a> to associate the lookups with those names</p></li><li><p>To index into these objects, they can wrap indices like <code>Int</code> or a <code>Selector</code></p></li></ul><p>This symmetry means we can ignore how data is organized, and label and access it by name, letting DD work out the details for us.</p><p>Dimensions are defined in the <a href="/DimensionalData.jl/dev/api/dimensions#DimensionalData.Dimensions"><code>DimensionalData.Dimensions</code></a> submodule, and some Dimension-specific methods can be brought into scope with:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> DimensionalData</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Dimensions</span></span></code></pre></div>`,13)])])}const D=a(o,[["render",t]]);export{h as __pageData,D as default};
